import React from 'react'
import { Routes, Route, Link } from 'react-router-dom';
import './HomePageButton.css';

function HomePageButton() {
    return (
        <Link
            to='/'
            style={{ textDecoration: 'none' }}
            className='homepage-button'>
        </Link>
    )
}

export default HomePageButton;
